int main() {
    int x, y;
    if (scanf("%d %d", &x, &y) == 2) {
        if (x == 0 && y == 0) printf("Point lies at the origin\n");
        else if (x > 0 && y > 0) printf("Point lies in the First quandrant\n");
        else if (x < 0 && y > 0) printf("Point lies in the Second quandrant\n");
        else if (x < 0 && y < 0) printf("Point lies in the Third quandrant\n");
        else if (x > 0 && y < 0) printf("Point lies in the Fourth quandrant\n");
    }
    return 0;
}

